 c.addEventListener('pointerdown',interact);$$('[data-block]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.block);mine=false;$('#block-type').textContent=b.textContent.trim();$('#build-mode').textContent='PLACE'});$('#mine-toggle').onclick=()=>{mine=!mine;$('#build-mode').textContent=mine?'MINE':'PLACE'};$('#reset-world').onclick=()=>{world=Array.from({length:N*N},()=>({h:1,type:1}));try{localStorage.removeItem('playroom-block-world')}catch{}render()};render();cleanup=()=>{};
